/**
 * Pure timing contract shared by the runtime watchdog and its deterministic
 * tests. The deadline is driven only by accumulated render-frame deltas.
 */
export const getCharacterAnimationWatchdogTiming = (
  clipDurationSeconds: number,
  timeScale: number,
  blendSeconds: number,
  marginSeconds = ANIMATION_WATCHDOG_MARGIN_SECONDS,
): CharacterAnimationWatchdogTiming => {
  const safeClipDuration = Number.isFinite(clipDurationSeconds)
    ? Math.max(0, clipDurationSeconds)
    : 0;
  const safeTimeScale = Number.isFinite(timeScale)
    ? Math.max(Math.abs(timeScale), 0.000_001)
    : 0.000_001;
  const safeBlend = Number.isFinite(blendSeconds) ? Math.max(0, blendSeconds) : 0;
  const safeMargin = Number.isFinite(marginSeconds) ? Math.max(0, marginSeconds) : 0;
  const expectedPlaybackSeconds = safeClipDuration / safeTimeScale;
  return {
    expectedPlaybackSeconds,
    blendSeconds: safeBlend,
    marginSeconds: safeMargin,
    deadlineSeconds: expectedPlaybackSeconds + safeBlend + safeMargin,
  };
};

export class CharacterRig {
  public readonly root = new THREE.Group();
  public modelLoaded = false;

  // Locomotion yaw stays on `root`; this child aligns the complete contact rig
  // to an inclined bridge without touching animation bones or their scale.
  private readonly surfaceTilt = new THREE.Group();
  private readonly poseRoot = new THREE.Group();
  private readonly contactShadow = new THREE.Mesh(
    new THREE.CircleGeometry(0.7, 48),
    new THREE.MeshBasicMaterial({
      color: "#8d918d",
      transparent: true,
      opacity: 0.1,
      depthWrite: false,
    }),
  );
  private mixer: THREE.AnimationMixer | null = null;
  private idleAction: THREE.AnimationAction | null = null;
  private runAction: THREE.AnimationAction | null = null;
  private runStopAction: THREE.AnimationAction | null = null;
  private turnAction: THREE.AnimationAction | null = null;
  private currentAction: THREE.AnimationAction | null = null;
  private actionBlend: ActionBlend | null = null;
  private runClipDuration = RUN_CYCLE_SECONDS;
  private idleClipDuration = 0;
  private runStopClipDuration = 0;
  private turnClipDuration = 0;
  private runClipName: string | null = null;
  private idleClipName: string | null = null;
  private runStopClipName: string | null = null;
  private turnClipName: string | null = null;
  private loadedModel: THREE.Object3D | null = null;
  private leftFoot: THREE.Object3D | null = null;
  private rightFoot: THREE.Object3D | null = null;
  private upperBodyRoot: THREE.Object3D | null = null;
  private upperBodyCompensationApplied = false;
  private upperBodyCompensationRadians = 0;
  private readonly upperBodyCompensation = new THREE.Quaternion();
  private readonly upperBodyCompensationInverse = new THREE.Quaternion();
  private readonly surfaceWorldQuaternion = new THREE.Quaternion();
  private readonly upperBodyParentWorldInverse = new THREE.Quaternion();
  private readonly upperBodyCompensationAxis = new THREE.Vector3();
  private animationPhase: CharacterAnimationPhase = "loading";
  private transitionToken = 0;
  private surfaceY = 0;
  private surfacePitchRadians = 0;
  private groundClearance = 0;
  private running = false;
  private reducedMotion = false;
  private desiredQuaternion = new THREE.Quaternion();
  private readonly viewQuaternion = new THREE.Quaternion();
  private turnStartYaw = 0;
  private turnYawDelta = 0;
  private turnReversed = false;
  private turnElapsed = 0;
  private turnPlaybackDuration = 0;
  private animationWatchdog: AnimationWatchdog | null = null;
  private animationWatchdogTimeoutCount = 0;
  private animationWatchdogRecoveryCount = 0;
  private ignoredFinishedEventCount = 0;
  private lastAnimationRecoveryReason: string | null = null;
  private lastAnimationRecoveryPhase: CharacterSettlingPhase | null = null;
  private lastAnimationRecoveryTransitionToken: number | null = null;
  private readonly suppressedFinishedEvents = new Set<CharacterSettlingPhase>();
  private readonly yawAxis = new THREE.Vector3(0, 1, 0);
  private readonly maxAnisotropy: number;
  private readonly createLoader: CharacterGltfLoaderFactory;
  private loadGeneration = 0;
  private disposed = false;

  private readonly handleMixerFinished = (event: { action: THREE.AnimationAction }): void => {
    if (this.running || this.reducedMotion) {
      return;
    }

    const watchdog = this.animationWatchdog;
    if (
      !watchdog
      || event.action !== watchdog.action
      || this.animationPhase !== watchdog.phase
      || this.transitionToken !== watchdog.transitionToken
    ) {
      this.ignoredFinishedEventCount += 1;
      return;
    }

    // A delayed event from a previous use of the same AnimationAction can
    // arrive after a fresh transition has begun. A genuine event cannot finish
    // before the active clip's frame-driven playback budget has elapsed.
    if (
      watchdog.elapsedSeconds + FINISHED_EVENT_EARLY_TOLERANCE_SECONDS
      < watchdog.expectedPlaybackSeconds
    ) {
      this.ignoredFinishedEventCount += 1;
      return;
    }

    // Fault injection must consume the genuine completion for the current
    // transition, never an early event left over from a previous clip use.
    if (this.suppressedFinishedEvents.delete(watchdog.phase)) {
      return;
    }

    if (watchdog.phase === "stopping") {
      this.transitionToRest();
      return;
    }

    if (watchdog.phase === "turning") {
      this.finishTurn();
    }
  };

  public constructor(
    maxAnisotropy = 4,
    createLoader: CharacterGltfLoaderFactory = () => new GLTFLoader(),
  ) {
    this.maxAnisotropy = Math.max(1, Math.min(maxAnisotropy, 8));
    this.createLoader = createLoader;
    this.root.name = "liu-kanshan-character-root";
    this.surfaceTilt.name = "liu-kanshan-surface-tilt";
    this.poseRoot.name = "liu-kanshan-pose-root";
    this.contactShadow.name = "liu-kanshan-contact-shadow";
    this.contactShadow.rotation.x = -Math.PI / 2;
    this.contactShadow.position.set(0, SHADOW_SURFACE_OFFSET, 0);
    this.contactShadow.scale.set(1.2, 0.55, 1);
    this.contactShadow.renderOrder = -1;
    this.root.add(this.surfaceTilt);
    this.surfaceTilt.add(this.contactShadow, this.poseRoot);
  }

  public async load(
    urls: CharacterAssetUrls,
    callbacks: CharacterLoadCallbacks = {},
  ): Promise<CharacterLoadResult> {
    if (this.disposed) {
      throw new DOMException("CharacterRig has been disposed.", "AbortError");
    }
    if (this.modelLoaded || this.loadedModel) {
      throw new Error("CharacterRig assets are already loaded.");
    }
    const loadGeneration = ++this.loadGeneration;
    const isCurrentLoad = (): boolean => (
      !this.disposed && loadGeneration === this.loadGeneration
    );
    const throwIfStale = (): void => {
      if (!isCurrentLoad()) {
        throw new DOMException("Character asset load was superseded or disposed.", "AbortError");
      }
    };
    const loader = this.createLoader();
    const progress = [0, 0, 0, 0];
    const progressKnown = [false, false, false, false];

    const reportProgress = (): void => {
      if (!isCurrentLoad()) return;
      if (progressKnown.every(Boolean)) {
        callbacks.onProgress?.(progress.reduce((sum, value) => sum + value, 0) / progress.length);
      } else {
        callbacks.onProgress?.(null);
      }
    };

    const loadAsset = async (url: string, index: number): Promise<GLTF> => {
      try {
        return await loader.loadAsync(url, (event) => {
          if (event.lengthComputable && event.total > 0) {
            progress[index] = event.loaded / event.total;
            progressKnown[index] = true;
          }
          reportProgress();
        });
      } finally {
        progress[index] = 1;
        progressKnown[index] = true;
        reportProgress();
      }
    };

    const loadOptionalAsset = async (
      url: string,
      index: number,
    ): Promise<{ gltf: GLTF | null; error: Error | null }> => {
      try {
        return { gltf: await loadAsset(url, index), error: null };
      } catch (error) {
        return {
          gltf: null,
          error: error instanceof Error ? error : new Error(String(error)),
        };
      }
    };

    const [runAsset, idleAsset, runStopAsset, turnAsset] = await Promise.all([
      loadOptionalAsset(urls.run, 0),
      loadOptionalAsset(urls.idle, 1),
      loadOptionalAsset(urls.runStop, 2),
      loadOptionalAsset(urls.turn, 3),
    ]);

    const warnings: string[] = [];
    const runGltf = runAsset.gltf;
    const model = runGltf?.scene ?? null;

    try {
      throwIfStale();
      if (!runGltf || !model) {
        throw runAsset.error ?? new Error("刘看山跑步模型加载失败。");
      }
      this.configureModel(model);

      const runSourceClip = this.requireClip(runGltf, RUN_CLIP_NAME);
      this.assertClipTargets(runSourceClip, model);
      const runClip = this.createSeamlessRunClip(runSourceClip);

      let idleSourceClip: THREE.AnimationClip | null = null;
      let idleClip: THREE.AnimationClip;
      let referencePose: AnimationReferencePose | null = null;
      if (idleAsset.gltf) {
        try {
          idleSourceClip = this.requireClip(idleAsset.gltf, IDLE_CLIP_NAME);
          this.assertClipTargets(idleSourceClip, model);
          idleClip = this.createSeamlessIdleClip(idleSourceClip);
          referencePose = this.getAnimationReferencePose(
            idleSourceClip,
            this.getClipTimeRange(idleSourceClip).start,
          );
        } catch (error) {
          warnings.push(`待机动画不可用，已启用稳定姿势降级：${this.describeError(error)}`);
          idleSourceClip = null;
          idleClip = this.createStaticPoseClip(
            runClip,
            runClip.duration * FALLBACK_IDLE_FRAME_RATIO,
          );
        }
      } else {
        warnings.push(`待机动画加载失败，已启用稳定姿势降级：${this.describeError(idleAsset.error)}`);
        idleClip = this.createStaticPoseClip(
          runClip,
          runClip.duration * FALLBACK_IDLE_FRAME_RATIO,
        );
      }

      if (!referencePose) {
        referencePose = this.getAnimationReferencePose(
          runClip,
          runClip.duration * FALLBACK_IDLE_FRAME_RATIO,
        );
      }

      let runStopSourceClip: THREE.AnimationClip | null = null;
      let runStopClip: THREE.AnimationClip | null = null;
      if (runStopAsset.gltf) {
        try {
          runStopSourceClip = this.requireClip(runStopAsset.gltf, RUN_STOP_CLIP_NAME);
          this.assertClipTargets(runStopSourceClip, model);
          runStopClip = this.createInPlaceRunStopClip(runStopSourceClip, referencePose);
        } catch (error) {
          warnings.push(`跑停动画不可用，将直接柔和衔接待机：${this.describeError(error)}`);
          runStopSourceClip = null;
        }
      } else {
        warnings.push(`跑停动画加载失败，将直接柔和衔接待机：${this.describeError(runStopAsset.error)}`);
      }

      let turnSourceClip: THREE.AnimationClip | null = null;
      let turnClip: THREE.AnimationClip | null = null;
      if (turnAsset.gltf) {
        try {
          turnSourceClip = this.requireClip(turnAsset.gltf, TURN_CLIP_NAME);
          this.assertClipTargets(turnSourceClip, model);
          turnClip = this.createInPlaceTurnClip(turnSourceClip, referencePose);
        } catch (error) {
          warnings.push(`转身动画不可用，将使用柔和朝向降级：${this.describeError(error)}`);
          turnSourceClip = null;
        }
      } else {
        warnings.push(`转身动画加载失败，将使用柔和朝向降级：${this.describeError(turnAsset.error)}`);
      }

      // No asynchronous boundary exists below this check: a disposed or newer
      // rig generation can never attach assets loaded by an older request.
      throwIfStale();
      this.poseRoot.add(model);
      this.loadedModel = model;
      this.leftFoot = model.getObjectByName("LeftFoot") ?? null;
      this.rightFoot = model.getObjectByName("RightFoot") ?? null;
      this.upperBodyRoot = model.getObjectByName("Spine02") ?? null;
      this.normalizeModel(model);

      this.mixer = new THREE.AnimationMixer(model);
      this.mixer.addEventListener("finished", this.handleMixerFinished);

      this.idleAction = this.mixer.clipAction(idleClip);
      this.idleAction.setLoop(THREE.LoopRepeat, Infinity);
      this.idleAction.clampWhenFinished = false;

      this.runAction = this.mixer.clipAction(runClip);
      this.runAction.setLoop(THREE.LoopRepeat, Infinity);
      this.runAction.clampWhenFinished = false;

      if (runStopClip) {
        this.runStopAction = this.mixer.clipAction(runStopClip);
        this.runStopAction.setLoop(THREE.LoopOnce, 1);
        this.runStopAction.clampWhenFinished = true;
      }

      if (turnClip) {
        this.turnAction = this.mixer.clipAction(turnClip);
        this.turnAction.setLoop(THREE.LoopOnce, 1);
        this.turnAction.clampWhenFinished = true;
      }

      this.runClipName = runSourceClip.name;
      this.runClipDuration = runClip.duration;
      this.idleClipName = idleSourceClip?.name ?? idleClip.name;
      this.idleClipDuration = idleClip.duration;
      this.runStopClipName = runStopSourceClip?.name ?? null;
      this.runStopClipDuration = runStopClip?.duration ?? 0;
      this.turnClipName = turnSourceClip?.name ?? null;
      this.turnClipDuration = turnClip?.duration ?? 0;
      this.modelLoaded = true;

      if (this.reducedMotion) {
        this.enterReducedMotionPose();
      } else if (this.running) {
        this.transitionToRun(0);
      } else {
        this.transitionToIdle(0);
      }
      this.mixer.update(0);
      this.alignAnimatedPose(model);

      return {
        runClipName: runSourceClip.name,
        runClipDuration: runClip.duration,
        runStopClipName: runStopSourceClip?.name ?? null,
        runStopClipDuration: runStopClip?.duration ?? 0,
        idleClipName: idleSourceClip?.name ?? idleClip.name,
        idleClipDuration: idleClip.duration,
        turnClipName: turnSourceClip?.name ?? null,
        turnClipDuration: turnClip?.duration ?? 0,
        warnings,
      };
    } catch (error) {
      if (isCurrentLoad()) {
        this.mixer?.removeEventListener("finished", this.handleMixerFinished);
        this.mixer?.stopAllAction();
      }
      if (model) {
        this.poseRoot.remove(model);
        this.disposeObjectResources(model);
      }
      if (isCurrentLoad()) {
        this.loadedModel = null;
        this.leftFoot = null;
        this.rightFoot = null;
        this.mixer = null;
        this.idleAction = null;
        this.runAction = null;
        this.runStopAction = null;
        this.turnAction = null;
        this.currentAction = null;
        this.actionBlend = null;
        this.animationWatchdog = null;
        this.modelLoaded = false;
        this.animationPhase = "loading";
      }
      throw error;
    } finally {
      if (idleAsset.gltf) {
        this.disposeObjectResources(idleAsset.gltf.scene);
        idleAsset.gltf.scene.clear();
      }
      if (runStopAsset.gltf) {
        this.disposeObjectResources(runStopAsset.gltf.scene);
        runStopAsset.gltf.scene.clear();
      }
      if (turnAsset.gltf) {
        this.disposeObjectResources(turnAsset.gltf.scene);
        turnAsset.gltf.scene.clear();
      }
    }
  }

  public setReducedMotion(value: boolean): void {
    if (this.reducedMotion === value) {
      return;
    }
    this.reducedMotion = value;
    if (!this.modelLoaded) {
      return;
    }

    if (value) {
      this.enterReducedMotionPose();
    } else if (this.running) {
      this.transitionToRun(IDLE_TO_RUN_BLEND_SECONDS);
    } else if (this.animationPhase === "reduced" && this.idleAction) {
      this.idleAction.paused = false;
      this.idleAction.play();
      this.currentAction = this.idleAction;
      this.setAnimationPhase("idle");
    } else {
      this.transitionToIdle(IDLE_TO_RUN_BLEND_SECONDS);
    }
  }

  public dispose(): void {
    if (this.disposed) return;
    this.disposed = true;
    this.loadGeneration += 1;
    this.mixer?.removeEventListener("finished", this.handleMixerFinished);
    this.mixer?.stopAllAction();
    if (this.mixer && this.loadedModel) {
      this.mixer.uncacheRoot(this.loadedModel);
    }

    if (this.loadedModel) {
      this.disposeObjectResources(this.loadedModel);
    }
    this.contactShadow.geometry.dispose();
    this.contactShadow.material.dispose();
    this.poseRoot.clear();
    this.loadedModel = null;
    this.leftFoot = null;
    this.rightFoot = null;
    this.upperBodyRoot = null;
    this.upperBodyCompensationApplied = false;
    this.upperBodyCompensationRadians = 0;
    this.upperBodyCompensation.identity();
    this.idleAction = null;
    this.runAction = null;
    this.runStopAction = null;
    this.turnAction = null;
    this.currentAction = null;
    this.actionBlend = null;
    this.animationWatchdog = null;
    this.suppressedFinishedEvents.clear();
    this.turnElapsed = 0;
    this.turnPlaybackDuration = 0;
    this.turnReversed = false;
    this.mixer = null;
    this.modelLoaded = false;
    this.animationPhase = "loading";
  }

  public setRunning(value: boolean): void {
    if (this.running === value) {
      return;
    }
    this.running = value;
    if (!this.modelLoaded || this.reducedMotion) {
      return;
    }

    if (value) {
      const blend = this.animationPhase === "stopping"
        ? STOP_TO_RUN_BLEND_SECONDS
        : this.animationPhase === "turning"
          ? TURN_TO_RUN_BLEND_SECONDS
          : IDLE_TO_RUN_BLEND_SECONDS;
      this.transitionToRun(blend);
    } else {
      this.transitionToStop();
    }
  }

  public setPosition(x: number, z: number, surfaceY: number): void {
    this.surfaceY = surfaceY;
    this.root.position.x = x;
    this.root.position.z = z;
    this.applyGroundSupport();
  }

  public setSurfacePitch(
    pitchRadians: number,
    deltaSeconds: number,
    maximumPitchRadians = MAX_SURFACE_PITCH_RADIANS,
  ): void {
    const safePitch = Number.isFinite(pitchRadians) ? pitchRadians : 0;
    const safeMaximumPitch = Number.isFinite(maximumPitchRadians)
      ? THREE.MathUtils.clamp(
        Math.abs(maximumPitchRadians),
        0,
        MAX_SURFACE_PITCH_RADIANS,
      )
      : MAX_SURFACE_PITCH_RADIANS;
    const targetPitch = THREE.MathUtils.clamp(
      safePitch,
      -safeMaximumPitch,
      safeMaximumPitch,
    );
    const blend = this.reducedMotion ? 1 : 1 - Math.exp(-Math.max(0, deltaSeconds) * 14);
    this.surfacePitchRadians = THREE.MathUtils.lerp(
      this.surfacePitchRadians,
      targetPitch,
      blend,
    );
    // The exported character faces local +Z. Negative local-X rotation raises
    // that forward axis along a positive path tangent.
    this.surfaceTilt.rotation.x = -this.surfacePitchRadians;
  }

  public getAnimationPhase(): CharacterAnimationPhase {
    return this.animationPhase;
  }

  /**
   * `animationPhase === "idle"` is published when the idle blend starts.  Rule
   * orchestration must wait until that blend has actually settled before it
   * treats the character as a stable special-platform occupant.
   */
  public isVisuallyIdle(): boolean {
    return this.animationPhase === "reduced"
      || (this.animationPhase === "idle" && this.actionBlend === null);
  }

  /**
   * Development/test fault injection: consume exactly one genuine finished
   * event for the requested settling phase. The frame-driven watchdog must then
   * close the transition. Stale events do not consume the injection.
   */
  public debugSuppressNextFinishedEvent(phase: CharacterSettlingPhase): void {
    this.suppressedFinishedEvents.add(phase);
  }

  /**
   * Development/test recovery entry. Production recovery uses the same path
   * automatically when the active frame budget expires.
   */
  public debugRecoverStalledAnimation(
    reason = "manual-dev-test-recovery",
  ): boolean {
    return this.recoverStalledAnimation(reason, false);
  }

  public getDebugState(): {
    readonly clipName: string | null;
    readonly clipDuration: number;
    readonly mixerTime: number;
    readonly running: boolean;
    readonly reducedMotion: boolean;
    readonly phase: CharacterAnimationPhase;
    readonly visuallyIdle: boolean;
    readonly activeClip: string | null;
    readonly transitionToken: number;
    readonly clips: {
      readonly idle: string | null;
      readonly run: string | null;
      readonly runStop: string | null;
      readonly turn: string | null;
      readonly idleDuration: number;
      readonly runDuration: number;
      readonly runStopDuration: number;
      readonly turnDuration: number;
    };
    readonly actions: {
      readonly idle: { readonly time: number; readonly weight: number } | null;
      readonly run: { readonly time: number; readonly weight: number } | null;
      readonly runStop: { readonly time: number; readonly weight: number } | null;
      readonly turn: { readonly time: number; readonly weight: number } | null;
    };
    readonly feet: {
      readonly leftWorld: readonly [number, number, number] | null;
      readonly rightWorld: readonly [number, number, number] | null;
    };
    readonly groundSupport: {
      readonly surfaceY: number;
      readonly clearance: number;
      readonly rootY: number;
    };
    readonly orientation: {
      readonly rootYawDegrees: number;
      readonly viewYawDegrees: number;
      readonly surfacePitchDegrees: number;
      readonly torsoCompensationDegrees: number;
      readonly visibleTorsoPitchDegrees: number;
      readonly turnProgress: number;
      readonly turnDirection: "left" | "right" | null;
    };
    readonly watchdog: CharacterAnimationWatchdogDebugState;
  } {
    const watchdog = this.animationWatchdog;
    return {
      clipName: this.runClipName,
      clipDuration: this.runClipDuration,
      mixerTime: this.mixer?.time ?? 0,
      running: this.running,
      reducedMotion: this.reducedMotion,
      phase: this.animationPhase,
      visuallyIdle: this.isVisuallyIdle(),
      activeClip: this.currentAction?.getClip().name ?? null,
      transitionToken: this.transitionToken,
      clips: {
        idle: this.idleClipName,
        run: this.runClipName,
        runStop: this.runStopClipName,
        turn: this.turnClipName,
        idleDuration: this.idleClipDuration,
        runDuration: this.runClipDuration,
        runStopDuration: this.runStopClipDuration,
        turnDuration: this.turnClipDuration,
      },
      actions: {
        idle: this.getActionDebugState(this.idleAction),
        run: this.getActionDebugState(this.runAction),
        runStop: this.getActionDebugState(this.runStopAction),
        turn: this.getActionDebugState(this.turnAction),
      },
      feet: {
        leftWorld: this.getObjectWorldPosition(this.leftFoot),
        rightWorld: this.getObjectWorldPosition(this.rightFoot),
      },
      groundSupport: {
        surfaceY: this.surfaceY,
        clearance: this.groundClearance,
        rootY: this.root.position.y,
      },
      orientation: {
        rootYawDegrees: Number(THREE.MathUtils.radToDeg(this.getYaw(this.root.quaternion)).toFixed(2)),
        viewYawDegrees: Number(THREE.MathUtils.radToDeg(this.getYaw(this.viewQuaternion)).toFixed(2)),
        surfacePitchDegrees: Number(
          THREE.MathUtils.radToDeg(this.surfacePitchRadians).toFixed(2),
        ),
        torsoCompensationDegrees: Number(
          THREE.MathUtils.radToDeg(this.upperBodyCompensationRadians).toFixed(2),
        ),
        visibleTorsoPitchDegrees: Number(
          THREE.MathUtils.radToDeg(
            this.surfacePitchRadians - this.upperBodyCompensationRadians,
          ).toFixed(2),
        ),
        turnProgress: Number(this.getTurnProgress().toFixed(4)),
        turnDirection: this.animationPhase === "turning"
          ? this.turnReversed ? "left" : "right"
          : null,
      },
      watchdog: {
        activePhase: watchdog?.phase ?? null,
        elapsedSeconds: Number((watchdog?.elapsedSeconds ?? 0).toFixed(4)),
        expectedPlaybackSeconds: Number(
          (watchdog?.expectedPlaybackSeconds ?? 0).toFixed(4),
        ),
        blendSeconds: Number((watchdog?.blendSeconds ?? 0).toFixed(4)),
        marginSeconds: Number((watchdog?.marginSeconds ?? 0).toFixed(4)),
        deadlineSeconds: Number((watchdog?.deadlineSeconds ?? 0).toFixed(4)),
        remainingSeconds: Number(
          Math.max(0, (watchdog?.deadlineSeconds ?? 0) - (watchdog?.elapsedSeconds ?? 0))
            .toFixed(4),
        ),
        transitionToken: watchdog?.transitionToken ?? null,
        timeoutCount: this.animationWatchdogTimeoutCount,
        recoveryCount: this.animationWatchdogRecoveryCount,
        ignoredFinishedEventCount: this.ignoredFinishedEventCount,
        lastRecoveryReason: this.lastAnimationRecoveryReason,
        lastRecoveryPhase: this.lastAnimationRecoveryPhase,
        lastRecoveryTransitionToken: this.lastAnimationRecoveryTransitionToken,
        suppressNextFinished: {
          stopping: this.suppressedFinishedEvents.has("stopping"),
          turning: this.suppressedFinishedEvents.has("turning"),
        },
      },
    };
  }

  public setFacing(x: number, z: number, deltaSeconds: number): void {
    const yaw = Math.atan2(x, z);
    this.desiredQuaternion.setFromAxisAngle(this.yawAxis, yaw);
    if (this.animationPhase !== "running" && this.animationPhase !== "stopping") {
      return;
    }
    const blend = this.reducedMotion ? 1 : 1 - Math.exp(-deltaSeconds * 11);
    this.root.quaternion.slerp(this.desiredQuaternion, blend);
  }

  public setViewFacing(x: number, z: number, deltaSeconds: number): void {
    const yaw = Math.atan2(x, z);
    this.viewQuaternion.setFromAxisAngle(this.yawAxis, yaw);
    if (
      this.animationPhase !== "idle"
      && this.animationPhase !== "reduced"
      && this.animationPhase !== "loading"
    ) {
      return;
    }
    const blend = this.reducedMotion ? 1 : 1 - Math.exp(-deltaSeconds * 9);
    this.root.quaternion.slerp(this.viewQuaternion, blend);
  }

  public update(deltaSeconds: number, _elapsedSeconds: number): void {
    this.removeUpperBodySlopeCompensation();
    this.updateActionBlend(deltaSeconds);
    this.applyGroundSupport();
    this.advanceAnimationWatchdog(deltaSeconds);
    if (this.mixer && !this.reducedMotion) {
      this.mixer.update(deltaSeconds);
    }
    this.updateTurnOrientation(deltaSeconds);
    this.recoverExpiredAnimationWatchdog();

    this.poseRoot.position.set(0, 0, 0);
    this.poseRoot.scale.set(1, 1, 1);
    this.applyUpperBodySlopeCompensation();
  }

  private configureModel(model: THREE.Object3D): void {
    model.name = "liu-kanshan-model";
    model.traverse((object) => {
      if (object instanceof THREE.Mesh || object instanceof THREE.SkinnedMesh) {
        object.castShadow = false;
        object.receiveShadow = true;
        object.frustumCulled = false;

        const materials = Array.isArray(object.material) ? object.material : [object.material];
        materials.forEach((material) => {
          if (material instanceof THREE.MeshStandardMaterial) {
            material.roughness = 0.42;
            material.metalness = 0;
            material.emissiveIntensity = 0.025;

            [material.map, material.emissiveMap].forEach((texture) => {
              if (texture) {
                texture.anisotropy = this.maxAnisotropy;
                texture.needsUpdate = true;
              }
            });
          }
          if (material instanceof THREE.MeshPhysicalMaterial) {
            material.specularIntensity = 0.82;
            material.specularColor.set("#ffffff");
          }
        });
      }
    });
  }

  private normalizeModel(model: THREE.Object3D): void {
    model.updateMatrixWorld(true);
    const bounds = new THREE.Box3().setFromObject(model);
    const size = bounds.getSize(new THREE.Vector3());
    const center = bounds.getCenter(new THREE.Vector3());

    if (!Number.isFinite(size.y) || size.y <= 0) {
      throw new Error("刘看山模型尺寸无效。 ");
    }

    const scale = HERO_HEIGHT / size.y;
    model.scale.multiplyScalar(scale);
    model.position.set(-center.x * scale, -bounds.min.y * scale, -center.z * scale);
    model.updateMatrixWorld(true);
  }

  private alignAnimatedPose(model: THREE.Object3D): void {
    const savedQuaternion = this.root.quaternion.clone();
    const savedPosePosition = this.poseRoot.position.clone();
    const savedPoseScale = this.poseRoot.scale.clone();

    this.root.quaternion.identity();
    this.poseRoot.position.set(0, 0, 0);
    this.poseRoot.scale.set(1, 1, 1);
    this.root.updateMatrixWorld(true);

    const bounds = new THREE.Box3().setFromObject(model, true);
    const center = bounds.getCenter(new THREE.Vector3());
    const poseOrigin = this.poseRoot.getWorldPosition(new THREE.Vector3());
    if (!bounds.isEmpty()) {
      model.position.x += poseOrigin.x - center.x;
      model.position.y += poseOrigin.y - bounds.min.y;
      model.position.z += poseOrigin.z - center.z;
    }

    this.root.quaternion.copy(savedQuaternion);
    this.poseRoot.position.copy(savedPosePosition);
    this.poseRoot.scale.copy(savedPoseScale);
    this.root.updateMatrixWorld(true);
  }

  private createSeamlessRunClip(sourceClip: THREE.AnimationClip): THREE.AnimationClip {
    const tracks = sourceClip.tracks.map((sourceTrack) => {
      const track = sourceTrack.clone();
      const valueSize = track.getValueSize();
      const keptIndices: number[] = [];

      for (let index = 0; index < track.times.length; index += 1) {
        const shiftedTime = (track.times[index] ?? 0) - SOURCE_CLIP_START_SECONDS;
        if (shiftedTime >= -0.0001 && shiftedTime < RUN_CYCLE_SECONDS - 0.0001) {
          keptIndices.push(index);
        }
      }

      if (keptIndices.length === 0) {
        return track;
      }

      const times = new Float32Array(keptIndices.length + 1);
      const values = new Float32Array((keptIndices.length + 1) * valueSize);
      keptIndices.forEach((sourceIndex, destinationIndex) => {
        times[destinationIndex] = Math.max(
          0,
          (track.times[sourceIndex] ?? SOURCE_CLIP_START_SECONDS) - SOURCE_CLIP_START_SECONDS,
        );
        for (let component = 0; component < valueSize; component += 1) {
          values[destinationIndex * valueSize + component] =
            track.values[sourceIndex * valueSize + component] ?? 0;
        }
      });

      times[times.length - 1] = RUN_CYCLE_SECONDS;
      for (let component = 0; component < valueSize; component += 1) {
        values[(times.length - 1) * valueSize + component] = values[component] ?? 0;
      }

      track.times = times;
      track.values = values;
      return track;
    });

    return new THREE.AnimationClip(`${sourceClip.name}-seamless`, RUN_CYCLE_SECONDS, tracks);
  }

  private createSeamlessIdleClip(sourceClip: THREE.AnimationClip): THREE.AnimationClip {
    const range = this.getClipTimeRange(sourceClip);
    const tracks = sourceClip.tracks.map((sourceTrack) => {
      const track = sourceTrack.clone();
      track.shift(-range.start);
      const valueSize = track.getValueSize();
      const lastOffset = (track.times.length - 1) * valueSize;
      for (let component = 0; component < valueSize; component += 1) {
        track.values[lastOffset + component] = track.values[component] ?? 0;
      }
      return track;
    });
    return new THREE.AnimationClip(
      `${sourceClip.name}-seamless`,
      range.end - range.start,
      tracks,
    );
  }

  private createStaticPoseClip(
    sourceClip: THREE.AnimationClip,
    sampleTime: number,
  ): THREE.AnimationClip {
    const tracks = sourceClip.tracks.map((sourceTrack) => {
      const track = sourceTrack.clone();
      const valueSize = track.getValueSize();
      const result = new Float32Array(valueSize);
      const sample = (track as InterpolatableTrack)
        .createInterpolant(result)
        .evaluate(sampleTime);
      const values = new Float32Array(valueSize * 2);
      values.set(sample, 0);
      values.set(sample, valueSize);
      track.times = new Float32Array([0, 1]);
      track.values = values;
      return track;
    });
    return new THREE.AnimationClip("liu-kanshan-static-idle-fallback", 1, tracks);
  }

  private createInPlaceRunStopClip(
    sourceClip: THREE.AnimationClip,
    referencePose: AnimationReferencePose,
  ): THREE.AnimationClip {
    const clip = THREE.AnimationUtils.subclip(
      sourceClip,
      "liu-kanshan-run-stop-in-place",
      STOP_START_FRAME,
      STOP_END_FRAME,
      CLIP_FPS,
    );

    clip.tracks.forEach((track) => {
      const binding = THREE.PropertyBinding.parseTrackName(track.name);
      if (binding.nodeName === "Hips" && binding.propertyName === "position") {
        for (let offset = 0; offset < track.values.length; offset += 3) {
          track.values[offset] = referencePose.position.x;
          track.values[offset + 2] = referencePose.position.z;
        }
      }

      if (
        binding.propertyName === "quaternion"
        && binding.nodeName
        && STABLE_BODY_BONES.has(binding.nodeName)
      ) {
        const referenceQuaternion = referencePose.stableBodyQuaternions.get(binding.nodeName);
        if (!referenceQuaternion) {
          throw new Error(`待机参考姿势缺少 ${binding.nodeName} 四元数。`);
        }
        for (let offset = 0; offset < track.values.length; offset += 4) {
          referenceQuaternion.toArray(track.values, offset);
        }
      }
    });
    clip.resetDuration();
    return clip;
  }

  private createInPlaceTurnClip(
    sourceClip: THREE.AnimationClip,
    referencePose: AnimationReferencePose,
  ): THREE.AnimationClip {
    const clip = THREE.AnimationUtils.subclip(
      sourceClip,
      "liu-kanshan-turn-in-place",
      TURN_START_FRAME,
      TURN_END_FRAME,
      CLIP_FPS,
    );
    clip.tracks.forEach((track) => {
      const binding = THREE.PropertyBinding.parseTrackName(track.name);
      if (binding.nodeName === "Hips" && binding.propertyName === "position") {
        for (let offset = 0; offset < track.values.length; offset += 3) {
          track.values[offset] = referencePose.position.x;
          track.values[offset + 2] = referencePose.position.z;
        }
      }
      if (
        binding.propertyName === "quaternion"
        && binding.nodeName
        && STABLE_BODY_BONES.has(binding.nodeName)
      ) {
        const referenceQuaternion = referencePose.stableBodyQuaternions.get(binding.nodeName);
        if (!referenceQuaternion) {
          throw new Error(`待机参考姿势缺少 ${binding.nodeName} 四元数。`);
        }
        for (let offset = 0; offset < track.values.length; offset += 4) {
          referenceQuaternion.toArray(track.values, offset);
        }
      }
    });
    clip.resetDuration();
    return clip;
  }

  private transitionToRun(blendSeconds: number): void {
    if (!this.runAction || this.animationPhase === "running") {
      return;
    }
    this.turnElapsed = 0;
    this.turnPlaybackDuration = 0;
    this.turnReversed = false;
    this.activateAction(this.runAction, RUN_TIME_SCALE, blendSeconds, 0);
    this.setAnimationPhase("running");
  }

  private transitionToStop(): void {
    if (this.animationPhase !== "running") {
      return;
    }
    if (!this.runStopAction) {
      this.transitionToRest(FALLBACK_RUN_TO_IDLE_BLEND_SECONDS);
      return;
    }
    this.activateAction(
      this.runStopAction,
      STOP_TIME_SCALE,
      RUN_TO_STOP_BLEND_SECONDS,
      0,
    );
    this.setAnimationPhase("stopping");
    this.beginAnimationWatchdog(
      "stopping",
      this.runStopAction,
      this.runStopClipDuration,
      STOP_TIME_SCALE,
      RUN_TO_STOP_BLEND_SECONDS,
    );
  }

  private transitionToRest(
    idleBlendSeconds = STOP_TO_IDLE_BLEND_SECONDS,
  ): void {
    const angleToViewer = this.root.quaternion.angleTo(this.viewQuaternion);
    if (!this.turnAction || angleToViewer <= TURN_ANGLE_THRESHOLD) {
      this.transitionToIdle(idleBlendSeconds);
      return;
    }

    this.turnStartYaw = this.getYaw(this.root.quaternion);
    const targetYaw = this.getYaw(this.viewQuaternion);
    const rawYawDelta = targetYaw - this.turnStartYaw;
    const yawDelta = Math.atan2(Math.sin(rawYawDelta), Math.cos(rawYawDelta));
    this.turnYawDelta = yawDelta;
    this.turnReversed = yawDelta > 0;
    this.turnElapsed = 0;
    this.turnPlaybackDuration = this.turnClipDuration / TURN_TIME_SCALE;
    this.activateAction(
      this.turnAction,
      this.turnReversed ? -TURN_TIME_SCALE : TURN_TIME_SCALE,
      STOP_TO_TURN_BLEND_SECONDS,
      this.turnReversed ? this.turnClipDuration : 0,
    );
    this.setAnimationPhase("turning");
    this.beginAnimationWatchdog(
      "turning",
      this.turnAction,
      this.turnClipDuration,
      TURN_TIME_SCALE,
      STOP_TO_TURN_BLEND_SECONDS,
    );
  }

  private finishTurn(): void {
    this.root.quaternion.copy(this.viewQuaternion);
    this.turnElapsed = this.turnPlaybackDuration;
    this.transitionToIdle(TURN_TO_IDLE_BLEND_SECONDS);
  }

  private transitionToIdle(blendSeconds: number): void {
    if (!this.idleAction || this.animationPhase === "idle") {
      return;
    }
    this.activateAction(this.idleAction, 1, blendSeconds, 0);
    this.setAnimationPhase("idle");
  }

  private activateAction(
    action: THREE.AnimationAction,
    timeScale: number,
    blendSeconds: number,
    startTime: number,
  ): void {
    const actions = this.getAnimationActions();
    const capturedWeights = actions.map((candidate) => ({
      action: candidate,
      weight: candidate.isScheduled() ? candidate.getEffectiveWeight() : 0,
    }));
    const targetWeight = capturedWeights.find((entry) => entry.action === action)?.weight ?? 0;
    const preserveTargetPhase = action.isRunning() && targetWeight > 0.0001;

    this.actionBlend = null;
    actions.forEach((candidate) => candidate.stopFading().stopWarping());

    if (!preserveTargetPhase) {
      action.reset();
      action.time = startTime;
    } else {
      action.enabled = true;
      action.paused = false;
    }
    action.setEffectiveTimeScale(timeScale);
    action.play();

    const totalWeight = capturedWeights.reduce((sum, entry) => sum + entry.weight, 0);
    const normalizedEntries = capturedWeights.map((entry): ActionBlendEntry => ({
      action: entry.action,
      fromWeight: totalWeight > 0.0001
        ? entry.weight / totalWeight
        : entry.action === action ? 1 : 0,
      toWeight: entry.action === action ? 1 : 0,
    }));

    normalizedEntries.forEach((entry) => {
      if (entry.fromWeight > 0 || entry.action === action) {
        entry.action.enabled = true;
        entry.action.play();
      }
      entry.action.setEffectiveWeight(entry.fromWeight);
    });

    if (blendSeconds > 0) {
      this.actionBlend = {
        target: action,
        duration: blendSeconds,
        elapsed: 0,
        entries: normalizedEntries,
      };
    } else {
      this.finishActionBlend(action, normalizedEntries);
    }
    this.currentAction = action;
  }

  private enterReducedMotionPose(): void {
    if (!this.mixer || !this.idleAction) {
      return;
    }
    // setTime() overwrites the animated bone pose. Remove our additive Spine02
    // correction first so the next frame never inverts a correction that is no
    // longer present in the mixer output.
    this.removeUpperBodySlopeCompensation();
    this.actionBlend = null;
    this.turnElapsed = 0;
    this.turnPlaybackDuration = 0;
    this.turnReversed = false;
    this.getAnimationActions().forEach((action) => {
      action.setEffectiveWeight(0);
      action.stop();
    });
    this.idleAction.reset();
    this.idleAction.enabled = true;
    this.idleAction.setEffectiveWeight(1);
    this.idleAction.setEffectiveTimeScale(1);
    this.idleAction.play();
    this.mixer.setTime(Math.min(REDUCED_IDLE_TIME, this.idleClipDuration));
    this.idleAction.paused = true;
    this.currentAction = this.idleAction;
    this.root.quaternion.copy(this.viewQuaternion);
    this.applyUpperBodySlopeCompensation();
    this.setAnimationPhase("reduced");
  }

  private setAnimationPhase(phase: CharacterAnimationPhase): void {
    this.animationWatchdog = null;
    this.animationPhase = phase;
    this.transitionToken += 1;
  }

  private updateActionBlend(deltaSeconds: number): void {
    const blend = this.actionBlend;
    if (!blend) {
      return;
    }

    blend.elapsed = Math.min(blend.duration, blend.elapsed + Math.max(0, deltaSeconds));
    const progress = blend.duration > 0 ? blend.elapsed / blend.duration : 1;
    const eased = progress * progress * (3 - 2 * progress);
    blend.entries.forEach((entry) => {
      entry.action.setEffectiveWeight(
        THREE.MathUtils.lerp(entry.fromWeight, entry.toWeight, eased),
      );
    });

    if (progress >= 1) {
      this.actionBlend = null;
      this.finishActionBlend(blend.target, blend.entries);
    }
  }

  private beginAnimationWatchdog(
    phase: CharacterSettlingPhase,
    action: THREE.AnimationAction,
    clipDurationSeconds: number,
    timeScale: number,
    blendSeconds: number,
  ): void {
    const timing = getCharacterAnimationWatchdogTiming(
      clipDurationSeconds,
      timeScale,
      blendSeconds,
    );
    this.animationWatchdog = {
      phase,
      action,
      transitionToken: this.transitionToken,
      expectedPlaybackSeconds: timing.expectedPlaybackSeconds,
      blendSeconds: timing.blendSeconds,
      marginSeconds: timing.marginSeconds,
      deadlineSeconds: timing.deadlineSeconds,
      elapsedSeconds: 0,
    };
  }

  private advanceAnimationWatchdog(deltaSeconds: number): void {
    const watchdog = this.animationWatchdog;
    if (!watchdog) {
      return;
    }
    if (
      this.animationPhase !== watchdog.phase
      || this.transitionToken !== watchdog.transitionToken
    ) {
      this.animationWatchdog = null;
      return;
    }
    watchdog.elapsedSeconds = Math.min(
      watchdog.deadlineSeconds,
      watchdog.elapsedSeconds + Math.max(0, deltaSeconds),
    );
  }

  private recoverExpiredAnimationWatchdog(): void {
    const watchdog = this.animationWatchdog;
    if (!watchdog || watchdog.elapsedSeconds < watchdog.deadlineSeconds) {
      return;
    }
    this.recoverStalledAnimation(`${watchdog.phase}-finished-timeout`, true);
  }

  private recoverStalledAnimation(reason: string, timedOut: boolean): boolean {
    const watchdog = this.animationWatchdog;
    if (
      !watchdog
      || this.animationPhase !== watchdog.phase
      || this.transitionToken !== watchdog.transitionToken
    ) {
      return false;
    }

    // Clear ownership before activating a replacement action. This also makes
    // any mixer.finished event dispatched during cleanup observably stale.
    this.animationWatchdog = null;
    this.animationWatchdogRecoveryCount += 1;
    if (timedOut) {
      this.animationWatchdogTimeoutCount += 1;
    }
    this.lastAnimationRecoveryReason = reason;
    this.lastAnimationRecoveryPhase = watchdog.phase;
    this.lastAnimationRecoveryTransitionToken = watchdog.transitionToken;
    this.suppressedFinishedEvents.delete(watchdog.phase);

    if (this.actionBlend?.target === watchdog.action) {
      this.actionBlend = null;
    }
    watchdog.action.stopFading().stopWarping();
    watchdog.action.setEffectiveWeight(0);
    watchdog.action.stop();

    if (watchdog.phase === "turning") {
      this.root.quaternion.copy(this.viewQuaternion);
      this.turnElapsed = this.turnPlaybackDuration;
      this.transitionToIdle(TURN_TO_IDLE_BLEND_SECONDS);
    } else {
      // Preserve the normal post-stop policy: if the route ended facing away
      // from the viewer, the independently watched turn phase still runs.
      this.transitionToRest(STOP_TO_IDLE_BLEND_SECONDS);
    }

    // Removing the failed action drops its clearance contribution. Re-apply
    // support immediately so no recovery frame leaves the feet below/above the
    // current road or platform surface.
    this.applyGroundSupport();
    return true;
  }

  private updateTurnOrientation(deltaSeconds: number): void {
    if (this.animationPhase !== "turning") {
      return;
    }
    this.turnElapsed = Math.min(
      this.turnPlaybackDuration,
      this.turnElapsed + Math.max(0, deltaSeconds),
    );
    const chronologicalProgress = this.getTurnProgress();
    const progress = this.turnReversed
      ? 1 - this.sampleTurnYawProgress(1 - chronologicalProgress)
      : this.sampleTurnYawProgress(chronologicalProgress);
    this.root.quaternion.setFromAxisAngle(
      this.yawAxis,
      this.turnStartYaw + this.turnYawDelta * progress,
    );
  }

  private finishActionBlend(
    target: THREE.AnimationAction,
    entries: readonly ActionBlendEntry[],
  ): void {
    entries.forEach((entry) => {
      if (entry.action === target) {
        entry.action.enabled = true;
        entry.action.setEffectiveWeight(1);
        entry.action.play();
      } else {
        entry.action.setEffectiveWeight(0);
        entry.action.stop();
      }
    });
  }

  private getAnimationActions(): THREE.AnimationAction[] {
    const actions: THREE.AnimationAction[] = [];
    if (this.idleAction) {
      actions.push(this.idleAction);
    }
    if (this.runAction) {
      actions.push(this.runAction);
    }
    if (this.runStopAction) {
      actions.push(this.runStopAction);
    }
    if (this.turnAction) {
      actions.push(this.turnAction);
    }
    return actions;
  }

  /**
   * Keep the legs and feet aligned to the real bridge pitch while allowing the
   * torso to remain gravity-aware. Spine02 is the first upper-body branch below
   * Hips, so this compensation does not alter either leg chain.
   */
  private applyUpperBodySlopeCompensation(): void {
    const upperBodyRoot = this.upperBodyRoot;
    const parent = upperBodyRoot?.parent ?? null;
    if (!upperBodyRoot || !parent) {
      this.upperBodyCompensationRadians = 0;
      return;
    }

    const absolutePitch = Math.abs(this.surfacePitchRadians);
    const excessPitch = THREE.MathUtils.clamp(
      absolutePitch - MAX_VISIBLE_TORSO_PITCH_RADIANS,
      0,
      MAX_TORSO_COMPENSATION_RADIANS,
    );
    const onset = THREE.MathUtils.smoothstep(
      absolutePitch,
      TORSO_COMPENSATION_START_RADIANS,
      TORSO_COMPENSATION_FULL_RADIANS,
    );
    const compensationRadians = Math.sign(this.surfacePitchRadians)
      * excessPitch
      * onset;
    this.upperBodyCompensationRadians = compensationRadians;
    if (Math.abs(compensationRadians) <= 0.000_001) {
      return;
    }

    // Hips carries animated yaw/roll, so its local X is not reliably the
    // bridge-width axis. Convert surfaceTilt's X axis through world space into
    // the current Hips parent space, then premultiply the animated Spine02 pose.
    this.root.updateMatrixWorld(true);
    this.surfaceTilt.getWorldQuaternion(this.surfaceWorldQuaternion);
    this.upperBodyCompensationAxis
      .set(1, 0, 0)
      .applyQuaternion(this.surfaceWorldQuaternion)
      .normalize();
    parent.getWorldQuaternion(this.upperBodyParentWorldInverse).invert();
    this.upperBodyCompensationAxis
      .applyQuaternion(this.upperBodyParentWorldInverse)
      .normalize();
    this.upperBodyCompensation.setFromAxisAngle(
      this.upperBodyCompensationAxis,
      compensationRadians,
    );
    upperBodyRoot.quaternion
      .premultiply(this.upperBodyCompensation)
      .normalize();
    this.upperBodyCompensationApplied = true;
  }

  private removeUpperBodySlopeCompensation(): void {
    if (!this.upperBodyCompensationApplied || !this.upperBodyRoot) {
      this.upperBodyCompensationApplied = false;
      return;
    }
    this.upperBodyCompensationInverse
      .copy(this.upperBodyCompensation)
      .invert();
    this.upperBodyRoot.quaternion
      .premultiply(this.upperBodyCompensationInverse)
      .normalize();
    this.upperBodyCompensationApplied = false;
  }

  private applyGroundSupport(): void {
    const runWeight = this.runAction?.getEffectiveWeight() ?? 0;
    const stopWeight = this.runStopAction?.getEffectiveWeight() ?? 0;
    const turnWeight = this.turnAction?.getEffectiveWeight() ?? 0;
    this.groundClearance = (
      runWeight * RUN_GROUND_CLEARANCE
      + stopWeight * STOP_GROUND_CLEARANCE
      + turnWeight * TURN_GROUND_CLEARANCE
    );
    this.root.position.y = this.surfaceY + this.groundClearance;
    this.contactShadow.position.y = SHADOW_SURFACE_OFFSET - this.groundClearance;
  }

  private getTurnProgress(): number {
    if (this.animationPhase !== "turning" || this.turnPlaybackDuration <= 0) {
      return this.animationPhase === "idle" && this.turnElapsed > 0 ? 1 : 0;
    }
    if (this.turnAction?.isScheduled()) {
      const localProgress = THREE.MathUtils.clamp(
        this.turnAction.time / Math.max(this.turnClipDuration, 0.0001),
        0,
        1,
      );
      return this.turnReversed ? 1 - localProgress : localProgress;
    }
    return THREE.MathUtils.clamp(this.turnElapsed / this.turnPlaybackDuration, 0, 1);
  }

  private sampleTurnYawProgress(time: number): number {
    const clampedTime = THREE.MathUtils.clamp(time, 0, 1);
    for (let index = 1; index < TURN_YAW_CURVE.length; index += 1) {
      const previous = TURN_YAW_CURVE[index - 1];
      const next = TURN_YAW_CURVE[index];
      if (!previous || !next || clampedTime > next.time) {
        continue;
      }
      const span = Math.max(0.0001, next.time - previous.time);
      const alpha = (clampedTime - previous.time) / span;
      return THREE.MathUtils.lerp(previous.value, next.value, alpha);
    }
    return 1;
  }

  private getYaw(quaternion: THREE.Quaternion): number {
    return new THREE.Euler().setFromQuaternion(quaternion, "YXZ").y;
  }

  private getActionDebugState(
    action: THREE.AnimationAction | null,
  ): { readonly time: number; readonly weight: number } | null {
    if (!action) {
      return null;
    }
    return {
      time: Number(action.time.toFixed(4)),
      weight: Number(action.getEffectiveWeight().toFixed(4)),
    };
  }

  private getObjectWorldPosition(
    object: THREE.Object3D | null,
  ): readonly [number, number, number] | null {
    if (!object) {
      return null;
    }
    const position = object.getWorldPosition(new THREE.Vector3());
    return [position.x, position.y, position.z] as const;
  }

  private requireClip(gltf: GLTF, clipName: string): THREE.AnimationClip {
    const clip = gltf.animations.find((candidate) => candidate.name === clipName);
    if (!clip) {
      throw new Error(
        `未找到动画 ${clipName}；实际包含：${gltf.animations.map((candidate) => candidate.name).join("、") || "无"}`,
      );
    }
    return clip;
  }

  private assertClipTargets(clip: THREE.AnimationClip, model: THREE.Object3D): void {
    const missingTargets = new Set<string>();
    clip.tracks.forEach((track) => {
      const binding = THREE.PropertyBinding.parseTrackName(track.name);
      if (binding.nodeName && !model.getObjectByName(binding.nodeName)) {
        missingTargets.add(binding.nodeName);
      }
    });
    if (missingTargets.size > 0) {
      throw new Error(`动画骨骼不兼容：${[...missingTargets].join("、")}`);
    }
  }

  private getAnimationReferencePose(
    clip: THREE.AnimationClip,
    sampleTime: number,
  ): AnimationReferencePose {
    const positionTrack = clip.tracks.find((track) => {
      const binding = THREE.PropertyBinding.parseTrackName(track.name);
      return binding.nodeName === "Hips" && binding.propertyName === "position";
    });
    if (!positionTrack) {
      throw new Error("动画缺少 Hips 根位置轨道。");
    }

    const positionResult = new Float32Array(3);
    const position = (positionTrack as InterpolatableTrack)
      .createInterpolant(positionResult)
      .evaluate(sampleTime);

    const stableBodyQuaternions = new Map<string, THREE.Quaternion>();
    STABLE_BODY_BONE_NAMES.forEach((boneName) => {
      const quaternionTrack = clip.tracks.find((track) => {
        const binding = THREE.PropertyBinding.parseTrackName(track.name);
        return binding.nodeName === boneName && binding.propertyName === "quaternion";
      });
      if (!quaternionTrack) {
        throw new Error(`动画缺少 ${boneName} 四元数轨道。`);
      }
      const quaternionResult = new Float32Array(4);
      const quaternionValues = (quaternionTrack as InterpolatableTrack)
        .createInterpolant(quaternionResult)
        .evaluate(sampleTime);
      stableBodyQuaternions.set(
        boneName,
        new THREE.Quaternion().fromArray(quaternionValues).normalize(),
      );
    });

    return {
      position: new THREE.Vector3().fromArray(position),
      stableBodyQuaternions,
    };
  }

  private getClipTimeRange(clip: THREE.AnimationClip): { start: number; end: number } {
    let start = Number.POSITIVE_INFINITY;
    let end = Number.NEGATIVE_INFINITY;
    clip.tracks.forEach((track) => {
      start = Math.min(start, track.times[0] ?? start);
      end = Math.max(end, track.times[track.times.length - 1] ?? end);
    });
    if (!Number.isFinite(start) || !Number.isFinite(end) || end <= start) {
      throw new Error(`动画 ${clip.name} 的时间轴无效。`);
    }
    return { start, end };
  }

  private disposeObjectResources(root: THREE.Object3D): void {
    const geometries = new Set<THREE.BufferGeometry>();
    const materials = new Set<THREE.Material>();
    const textures = new Set<THREE.Texture>();
    const skeletons = new Set<THREE.Skeleton>();
    root.traverse((object) => {
      if (object instanceof THREE.Mesh) {
        geometries.add(object.geometry);
        const objectMaterials = Array.isArray(object.material)
          ? object.material
          : [object.material];
        objectMaterials.forEach((material) => {
          materials.add(material);
          Object.values(material).forEach((value) => {
            if (value instanceof THREE.Texture) {
              textures.add(value);
            }
          });
        });
      }
      if (object instanceof THREE.SkinnedMesh) {
        skeletons.add(object.skeleton);
      }
    });
    textures.forEach((texture) => texture.dispose());
    materials.forEach((material) => material.dispose());
    geometries.forEach((geometry) => geometry.dispose());
    skeletons.forEach((skeleton) => skeleton.dispose());
  }

  private describeError(error: unknown): string {
    return error instanceof Error ? error.message : String(error ?? "未知错误");
  }
}
